    "/api/v1/auth/token": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * 交換 Authorization Code 獲取 Token
         * @description App 使用 OAuth 流程取得的 authorization code 交換 JWT token。此 endpoint 用於 OAuth 2.0 Authorization Code Flow，避免 token 直接暴露在 redirect URL 中。
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: {
                content: {
                    "application/json": {
                        /** @description OAuth 流程取得的 authorization code */
                        code: string;
                    };
                };
            };
            responses: {
                /** @description Token 交換成功 */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @description JWT access token */
                            accessToken: string;
                            /** @enum {string} */
                            tokenType: "Bearer";
                            /** @description Token 有效期（秒） */
                            expiresIn: number;
                            /** @description Refresh token */
                            refreshToken: string;
                            user: {
                                /** @description 用戶 ID */
                                id: string;
                                /** @description 用戶 email */
                                email: string;
                                /** @description 用戶名稱 */
                                name: string;
                                /** @description 用戶頭像 URL */
                                avatar: string;
                            };
                        };
                    };
                };
                400: components["responses"]["BadRequestError"];
                401: components["responses"]["UnauthorizedError"];
                500: components["responses"]["InternalServerError"];
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
